        // ---------- Học tập, giảng dạy của tôi ----------
        ("Buổi dạy hôm nay, các lớp đang dạy và chuyên đề đủ điều kiện dạy. Điểm danh và nhập điểm cho lớp mình dạy.", "Today's sessions, classes you teach and subjects you're qualified for. Take attendance and enter scores for your classes.", "ຄາບສອນມື້ນີ້, ຫ້ອງທີ່ກຳລັງສອນ ແລະ ວິຊາທີ່ມີເງື່ອນໄຂສອນ. ເຊັກຊື່ ແລະ ປ້ອນຄະແນນໃຫ້ຫ້ອງທີ່ຕົນສອນ."),
        ("Điểm danh đi làm hôm nay", "Today's work check-in", "ລົງຊື່ເຂົ້າວຽກມື້ນີ້"),
        ("Bạn chưa điểm danh hôm nay. Trước {0} ghi \"Có mặt\", sau đó ghi \"Đi muộn\".", "You haven't checked in today. Before {0} it counts as \"Present\", after that \"Late\".", "ທ່ານຍັງບໍ່ໄດ້ລົງຊື່ມື້ນີ້. ກ່ອນ {0} ບັນທຶກ \"ມາ\", ຫຼັງຈາກນັ້ນ \"ມາຊ້າ\"."),
        ("Lịch học, tự điểm danh trong khung giờ, kết quả học tập và lịch sử chuyên cần của bạn.", "Your schedule, self check-in within the window, results and attendance history.", "ຕາຕະລາງຮຽນ, ເຊັກຊື່ເອງໃນຊ່ວງເວລາ, ຜົນການຮຽນ ແລະ ປະຫວັດຄວາມດຸໝັ່ນຂອງທ່ານ."),
        ("Chưa có buổi nào đang mở cổng.", "No session is open for check-in.", "ຍັງບໍ່ມີຄາບໃດເປີດໃຫ້ເຊັກຊື່."),
        ("Buổi kế tiếp: {ten}, Thứ Tư {0} lúc {1} (cổng mở {2}).", "Next session: {ten}, Wednesday {0} at {1} (check-in opens {2}).", "ຄາບຕໍ່ໄປ: {ten}, ວັນພຸດ {0} ເວລາ {1} (ເປີດເຊັກຊື່ {2})."),
        ("Tiến độ khoá học", "Course progress", "ຄວາມຄືບໜ້າຂອງລຸ້ນ"),
        ("học kỳ có kết quả", "semesters with results", "ພາກຮຽນທີ່ມີຜົນ"),
        ("Học lực:", "Standing:", "ຜົນການຮຽນ:"),
        ("Quy đổi theo điểm chữ", "Letter-grade conversion", "ແປງເປັນຄະແນນຕົວອັກສອນ"),
        ("Khối lượng đạt", "Credits passed", "ປະລິມານທີ່ຜ່ານ"),
        ("môn đạt /", "subjects passed /", "ວິຊາຜ່ານ /"),
        ("môn có điểm", "subjects graded", "ວິຊາທີ່ມີຄະແນນ"),
        ("Chưa đạt · chờ điểm", "Not passed · awaiting score", "ບໍ່ທັນຜ່ານ · ລໍຖ້າຄະແນນ"),
        ("Cần đăng ký thi lại/học lại", "Needs a resit or retake", "ຕ້ອງລົງທະບຽນສອບຄືນ/ຮຽນຄືນ"),
        ("Từ {0} trở lên", "{0} and above", "ແຕ່ {0} ຂຶ້ນໄປ"),
        ("TB năm", "Year average", "ສະເລ່ຍປີ"),
        ("/{0} của khoá", "/{0} of the course", "/{0} ຂອງລຸ້ນ"),
